'use client';

/*
 * Consent banner (shadcn/ui), "pelure" style — generated by `zeste add --style pelure`.
 * Banner in the theme colors (primary), with outlines and offset shadows in `foreground`.
 * "Deny all" and "Accept all" deliberately use the same variant (EU consent rules: equal prominence).
 */
import { ConsentBanner, useZeste } from '@zeste/react';
import type { Messages } from '@zeste/services/i18n/types';
import { Button } from '%UI%/button';

const chunky =
  'border-foreground h-auto rounded-[10px] border-[2.5px] px-[18px] py-2.5 font-bold shadow-[4px_4px_0_var(--foreground)] active:translate-x-[2px] active:translate-y-[2px] active:shadow-[2px_2px_0_var(--foreground)]';

export function CookieBanner() {
  const zeste = useZeste<Messages>();
  const t = zeste.messages;

  return (
    <>
      {zeste.needsReload && (
        // An already-loaded script was refused: it only really stops on reload.
        <div
          role="status"
          className="bg-primary border-foreground fixed top-4 right-4 z-50 rounded-[14px] border-[3px] p-3 shadow-[6px_6px_0_var(--foreground)]"
        >
          <Button variant="secondary" className={chunky} onClick={() => location.reload()}>
            {t.reload}
          </Button>
        </div>
      )}

      <ConsentBanner
        aria-label={t.icon}
        className="bg-primary text-primary-foreground border-foreground fixed inset-x-0 bottom-0 z-50 flex flex-wrap items-center gap-x-6 gap-y-3.5 border-t-[3px] px-6 py-5"
      >
        <div className="grid min-w-0 flex-[1_1_20rem] gap-1">
          <span className="text-2xl leading-none font-extrabold tracking-tight">{t.icon}</span>
          <p className="text-[15px] font-medium">{t.alertBigPrivacy}</p>
        </div>
        <div className="flex flex-wrap items-center gap-2.5">
          <Button variant="secondary" className={chunky} {...zeste.actions.denyAll}>
            {t.denyAll}
          </Button>
          <Button variant="secondary" className={chunky} {...zeste.actions.acceptAll}>
            {t.acceptAll}
          </Button>
          <Button variant="link" className="text-primary-foreground font-bold" {...zeste.actions.openPreferences}>
            {t.personalize}
          </Button>
        </div>
      </ConsentBanner>
    </>
  );
}
